function unitOptions(current=''){const values=[...defaultUnits,...(config.payload.units||[]),...config.payload.catalog.map(x=>x.unit),...all.flatMap(x=>[...(x.payload.offer||[]),...(x.payload.works||[])].map(l=>l.unit)),current];const result=[],seen=new Set();for(const value of values){const unit=cleanUnit(value),key=unit.toLocaleLowerCase('pl');if(unit&&!seen.has(key)){seen.add(key);result.push(unit);}}return result;}
function unitField(current='',required=true){const options=unitOptions(current),value=options.find(x=>x.toLocaleLowerCase('pl')===cleanUnit(current).toLocaleLowerCase('pl'))||'';return `<div class="field"><label for="f-unit">Jednostka</label><select id="f-unit" name="unit" ${required?'required':''}><option value="">Wybierz jednostkę</option>${options.map(x=>`<option value="${esc(x)}" ${x===value?'selected':''}>${esc(x)}</option>`).join('')}<option value="${customUnitValue}">Dodaj własną…</option></select></div><div id="custom-unit-field" hidden>${input('customUnit','Własna jednostka','','text','disabled maxlength="40"')}<p class="muted">Po zapisaniu będzie dostępna na liście przy kolejnych pracach.</p></div>`;}
