async function rememberUnit(unit){if(!unit||[...defaultUnits,...(configBaseline.payload.units||[])].some(x=>x.toLocaleLowerCase('pl')===unit.toLocaleLowerCase('pl')))return;const payload=structuredClone(configBaseline.payload);payload.units=[...(payload.units||[]),unit];const result=await API.saveSettings(payload,configBaseline.revision),row=Array.isArray(result)?result[0]:result;config.payload.units=structuredClone(row.payload.units);config.revision=row.revision;configBaseline=structuredClone(row);}
