async function removeProject(id){if(busy)return;const project=all.find(x=>x.id===id);if(!project)return;if(!confirm(`Usunąć inwestycję „${project.payload.name}” (${project.contract_number})?\n\nUsunięte zostaną jej pomieszczenia, prace, rozliczenia i historia. Tej operacji nie można cofnąć. Numer umowy nie zostanie użyty ponownie.`))return;busy=true;try{const deleted=await API.deleteProject(project);if(deleted!==project.id)throw new Error('Nie potwierdzono usunięcia inwestycji. Odśwież listę.');all=all.filter(x=>x.id!==id);if(selected?.id===id){selected=null;view='dashboard';dirty=false;}render();toast('Usunięto inwestycję.');}finally{busy=false;}}
async function save(){if(busy)return;busy=true;try{const data=structuredClone(p()),previous=all.find(s=>s.id===selected.id)?.payload;
 if(previous&&!(previous.works.length===0&&data.acceptedOffers.length>previous.acceptedOffers.length)){const normalize=rows=>rows.map(({done,...rest})=>rest);const changed=C.changeRecord(normalize(previous.works),normalize(data.works));data.changes.push(...changed);}
 const row=await API.saveProject(selected,data);selected=Array.isArray(row)?row[0]:row;all=all.map(x=>x.id===selected.id?structuredClone(selected):x);dirty=false;render();toast('Zapisano zmiany.');
 }finally{busy=false;}}
async function saveConfig(){if(busy)return;busy=true;try{const row=await API.saveSettings(config.payload,config.revision);config=Array.isArray(row)?row[0]:row;configBaseline=structuredClone(config);dirty=false;render();toast('Zapisano ustawienia.');}finally{busy=false;}}
function pdfDialog(){if(dirty){toast('Zapisz zmiany przed przygotowaniem dokumentu.');return;}const initial=view==='overview'?PDF.MODULES.map(([key])=>key):[view];modal('Wybierz części dokumentu PDF',`<p class="muted">Wybrane części zostaną połączone w jeden dokument. Każda rozpocznie się na nowej stronie.</p><div class="row" style="margin-bottom:16px">${btn('pdf-all','Zaznacz wszystkie')}${btn('pdf-none','Odznacz wszystkie')}</div><div class="pdf-choices">${PDF.MODULES.map(([key,label])=>`<label class="pdf-choice"><input type="checkbox" name="pdfModule" value="${key}" ${initial.includes(key)?'checked':''}><span>${esc(label)}</span></label>`).join('')}</div>`,fd=>{const modules=fd.getAll('pdfModule');if(!modules.length)throw new Error('Wybierz przynajmniej jedną część dokumentu.');printDoc(view,null,modules);},null,'','Otwórz dokument PDF');}
function printDoc(which=view,offer,modules){if(dirty)throw new Error('Zapisz zmiany przed przygotowaniem dokumentu.');const logoUrl=new URL('./assets/robisie-logo.png?v='+C.VERSION,window.location.href).href,html=PDF.buildDocument(selected,config.payload,{modules:modules||[which==='overview'?'data':which],logoUrl,offer});const win=window.open('','_blank');if(!win)throw new Error('Zezwól na otwarcie dokumentu w nowej karcie.');win.document.write(html);win.document.close();}
document.addEventListener('submit',async e=>{if(e.target.id!=='login')return;e.preventDefault();const f=new FormData(e.target),b=e.target.querySelector('button');b.disabled=true;try{await API.login(f.get('email'),f.get('password'));await load();}catch(err){loginView(err.message);}});
document.addEventListener('input',e=>{const el=e.target;
 if(el.id==='search-projects'){$('#project-list').innerHTML=projectRows(all.filter(x=>JSON.stringify([x.payload.name,x.payload.investor,x.payload.address,x.contract_number]).toLocaleLowerCase('pl').includes(el.value.toLocaleLowerCase('pl'))));return;}
 if(el.dataset.field){p()[el.dataset.field]=el.type==='number'?C.number(el.value):el.value;markDirty();}
 if(el.dataset.handover){p().handover[el.dataset.handover]=el.type==='checkbox'?el.checked:el.value;markDirty();}
 if(el.dataset.config){config.payload[el.dataset.config]=C.number(el.value);markDirty();}
 if(el.dataset.company){config.payload.company[el.dataset.company]=el.value;markDirty();}
 if(el.dataset.line){const l=p()[el.dataset.kind].find(x=>x.id===el.dataset.line);l[el.dataset.prop]=el.type==='checkbox'?el.checked:C.number(el.value);markDirty();}
});
document.addEventListener('toggle',e=>{const el=e.target,key=el.dataset?.roomGroup;if(!key||!el.isConnected)return;if(el.open)openRoomGroups.add(key);else openRoomGroups.delete(key);},true);
document.addEventListener('change',e=>{if(e.target.id==='line-room'){lineFilter=e.target.value;render();}else if(e.target.dataset.line||e.target.dataset.field==='discount'||e.target.dataset.field==='workDiscount')render();});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;try{
 if(a==='close'){$('#dialog').close();return;}if(a==='delete')return;
 if(a==='menu'){mobileOpen=!mobileOpen;$('nav').classList.toggle('open',mobileOpen);return;}
 if(a==='logout'){if(!checkDirty())return;API.logout();selected=null;dirty=false;loginView();return;}
 if(a==='reload'){await load();return;}
 if(a==='nav'||a==='back'||a==='open'){if(!checkDirty())return;if(dirty){if(selected)selected=structuredClone(all.find(x=>x.id===selected.id));config=structuredClone(configBaseline);}dirty=false;mobileOpen=false;if(a==='open'){selected=structuredClone(all.find(x=>x.id===id));view='overview';}else if(a==='back'){selected=null;view='dashboard';}else view=b.dataset.view;lineFilter='';shopFilter=null;render();window.scrollTo(0,0);return;}
 if(a==='new-project'){modal('Nowa inwestycja',input('name','Nazwa inwestycji','','text','required')+input('investor','Imię i nazwisko inwestora','','text','required')+input('date','Data nadania numeru umowy',C.today(),'date','required')+'<p class="muted">Numer zostanie nadany w bazie według schematu UUR-RS/rok/miesiąc/kolejny numer w danym miesiącu.</p>',async fd=>{const row=await API.createProject(C.newProject(fd.get('name'),fd.get('investor'),fd.get('date')),fd.get('date'));selected=Array.isArray(row)?row[0]:row;all.unshift(structuredClone(selected));view='data';dirty=false;});return;}
 if(a==='project-delete'){b.disabled=true;await removeProject(id);return;}
 if(a==='save'){b.disabled=true;await save();return;}if(a==='save-settings'){b.disabled=true;await saveConfig();return;}
 if(a==='room-add'||a==='room-edit'){roomDialog(id);return;}
 if(a==='line-add'||a==='line-edit'){lineDialog(b.dataset.kind,id);return;}
 if(a==='use-area'){const room=p().rooms.find(r=>r.id===$('#f-roomId').value);if(!room){toast('Wybierz pomieszczenie.');return;}$('#f-qty').value=C.roomArea(room)[b.dataset.area];$('#f-unit').value=b.dataset.area==='perimeter'?'mb':'m²';return;}
 if(a==='receipt-add'||a==='receipt-edit'){receiptDialog(id);return;}
 if(a==='purchase-shop'){shopFilter=b.dataset.all==='true'?null:b.dataset.shop;render();return;}
 if(a==='purchase-add'||a==='purchase-edit'){purchaseDialog(id);return;}
 if(a==='stage-add'||a==='stage-edit'){stageDialog(id);return;}
 if(a==='journal-add'||a==='journal-edit'){journalDialog(id);return;}
 if(a==='service-add'||a==='service-edit'){serviceDialog(id);return;}
 if(a==='accept-offer'){if(!p().offer.some(l=>l.included!==false&&l.qty>0))throw new Error('Dodaj przynajmniej jedną pracę z ilością.');if(!confirm('Zapisać tę ofertę jako zaakceptowaną przez inwestora? Jej treść pozostanie w historii.'))return;
 p().acceptedOffers.push({version:p().acceptedOffers.length+1,date:C.today(),lines:structuredClone(p().offer),discount:p().discount,materialEstimate:p().materialEstimate});
 if(!p().works.length){p().works=structuredClone(p().offer);p().workDiscount=p().discount;}p().status='oferta';markDirty();await save();return;}
 if(a==='change-accept'){const change=p().changes.find(x=>x.id===id);change.accepted=true;change.acceptedDate=C.today();markDirty();await save();return;}
 if(a==='contract-edit'){modal('Treść umowy',text('body','Treść',p().contractText||C.contractTemplate(selected,config.payload),'style="min-height:50vh"'),fd=>{p().contractText=fd.get('body');markDirty();});return;}
 if(a==='contract-generate'){if(p().contractText&&!confirm('Zastąpić edytowaną treść umowy tekstem z aktualnych danych?'))return;p().contractText=C.contractTemplate(selected,config.payload);markDirty();render();return;}
 if(a==='finish'){if(!p().handover.date)throw new Error('Uzupełnij datę odbioru.');if(!p().handover.accepted)throw new Error('Prace muszą być zaakceptowane przed zakończeniem inwestycji.');p().status='zakonczona';markDirty();await save();return;}
 if(a==='pdf-all'||a==='pdf-none'){for(const checkbox of $('#dialog').querySelectorAll('input[name="pdfModule"]'))checkbox.checked=a==='pdf-all';return;}
 if(a==='print'){pdfDialog();return;}if(a==='offer-print'){printDoc('offer',p().acceptedOffers.find(x=>x.version===Number(b.dataset.version)));return;}
 }catch(err){toast(err.message);}finally{if(b.isConnected)b.disabled=false;}});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
start();
